def authorize(user, required_scope: str) -> None:
    if required_scope not in user.scopes:   # scopes 如 {"read:db","call:email"}
        raise PermissionError(f"user lacks scope {required_scope}")

def execute_tool(user, tool_name, args):
    tool = TOOL_REGISTRY[tool_name]
    authorize(user, tool.required_scope)     # 不放行就抛错，工具不执行
    return tool.run(args)

# 检索质量：手算 Recall@K / MRR / NDCG@K
def recall_at_k(relevant_ids, retrieved_ids, k):
    hit = len(set(relevant_ids) & set(retrieved_ids[:k]))
    return hit / len(relevant_ids)                      # 分母=总相关数

def mrr(relevant_ids_per_q, retrieved_per_q):
    s = 0.0
    for rel, ret in zip(relevant_ids_per_q, retrieved_per_q):
        for i, doc_id in enumerate(ret, 1):             # 1-based 排名
            if doc_id in rel:
                s += 1.0 / i; break
    return s / len(retrieved_per_q)

def dcg_at_k(rels, k):                                  # rels: 前k位相关性等级[2,0,1]
    return sum((2**r - 1) / log2(i + 1) for i, r in enumerate(rels[:k], 1))
def ndcg_at_k(rels, k):
    ideal = sorted(rels, reverse=True)
    return dcg_at_k(rels, k) / dcg_at_k(ideal, k)

# ===== 阶段 A：连接各 Server，建统一 tools 表（只跑一次）=====
def bootstrap(host_config):
    clients = {}            # server_name -> MCPClient
    tool_registry = {}      # tool_name -> {"kind": "mcp"/"local", "target": ...}
    TOOLS_SCHEMA.clear()
    local_funcs = host_config["local_functions"]   # 本地函数: {name: callable}

    for srv in host_config["mcp_servers"]:
        client = connect(srv)              # A1：stdio spawn 或 http 常驻
        client.initialize()                # A2：握手（必须，否则 tools/list 不响应）
        for t in client.list_tools():      # A3：tools/list
            tool_registry[t["name"]] = {"kind": "mcp", "target": client}
            TOOLS_SCHEMA.append(t["schema"])     # A4：并入 tools 表
    for name, fn in local_funcs.items():
        tool_registry[name] = {"kind": "local", "target": fn}
        TOOLS_SCHEMA.append(fn.schema)            # 本地函数 schema 也并入

# ===== 阶段 B：一轮用户提问到最终回答 =====
def run_turn(user_msg, messages, llm):
    messages.append({"role": "user", "content": user_msg})
    while True:
        resp = llm.chat(messages=messages, tools=TOOLS_SCHEMA)   # ② 请求 LLM
        if not resp.tool_calls:                                  # ⑥ 无 tool_calls → 结束
            messages.append({"role": "assistant", "content": resp.text})
            return resp.text                                      # ⑦ 打印给用户
        # ③ LLM 只提议；④ 路由分发（此处顺序示例，生产可用线程池并发）
        messages.append({"role": "assistant", "content": None,
                         "tool_calls": resp.tool_calls})
        for call in resp.tool_calls:                             # 可并行执行
            entry = tool_registry[call.name]
            try:
                if entry["kind"] == "mcp":
                    obs = entry["target"].call_tool(call.name, call.args)   # 走 MCP
                else:
                    obs = entry["target"](**call.args)                     # 本地函数, 不走 MCP
            except Exception as e:
                obs = f"ERROR: {e}"                                # 失败也回填, 让模型知道
            # ⑤ 以 tool_call_id 回写 observation
            messages.append({"role": "tool",
                             "tool_call_id": call.id,
                             "content": str(obs)})
        # 回到循环顶部再求 LLM（⑥ 的多轮 ReAct 循环）

# 极简 MCP Server：注册一个 "加法" 工具
from mcp import Server

app = Server("demo-server")

@app.list_tools()                 # ① 声明能力清单
async def list_tools():
    return [{
        "name": "add",
        "description": "两个整数相加",
        "inputSchema": {           # 用 JSON Schema 描述入参
            "type": "object",
            "properties": {
                "a": {"type": "integer"},
                "b": {"type": "integer"}
            },
            "required": ["a", "b"]
        }
    }]

@app.call_tool()                  # ② 响应调用
async def call_tool(name, arguments):
    if name == "add":
        result = arguments["a"] + arguments["b"]
        return [{"type": "text", "text": str(result)}]

